schema.code:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://faion.net/schemas/internal-link-audit.json",
  "title": "Internal Link Audit report",
  "type": "object",
  "required": ["site", "audit_period", "crawl", "incoming_counts", "orphans", "clusters", "anchor_text", "hygiene_findings", "rewire_plan", "gsc_baseline", "remeasurement"],
  "additionalProperties": false,
  "definitions": {
    "date": {"type": "string", "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}$"},
    "url": {"type": "string", "pattern": "^https?://[^ ]+$"},
    "count": {"type": "integer", "minimum": 0},
    "generic_anchor": {"enum": ["click here", "read more", "this article", "here", "link", ""]}
  },
  "properties": {
    "__faion_header__": {"type": ["object", "string"]},
    "site": {"type": "string", "pattern": "^[a-z0-9.-]+\\.[a-z]{2,}$"},
    "audit_period": {
      "type": "object",
      "required": ["start", "end"],
      "additionalProperties": false,
      "properties": {"start": {"$ref": "#/definitions/date"}, "end": {"$ref": "#/definitions/date"}}
    },
    "crawl": {
      "type": "object",
      "required": ["crawler", "crawl_date", "javascript_rendered", "indexable_pages", "sitemap_urls", "cms_published_pages", "discrepancies"],
      "additionalProperties": false,
      "properties": {
        "crawler": {"type": "string", "minLength": 3},
        "crawl_date": {"$ref": "#/definitions/date"},
        "javascript_rendered": {"const": true},
        "indexable_pages": {"type": "integer", "minimum": 30},
        "sitemap_urls": {"type": "integer", "minimum": 1},
        "cms_published_pages": {"type": "integer", "minimum": 1},
        "discrepancies": {
          "type": "array",
          "items": {
            "type": "object",
            "required": ["source", "gap_pct", "explanation", "note"],
            "additionalProperties": false,
            "properties": {
              "source": {"type": "string", "enum": ["sitemap", "cms"]},
              "gap_pct": {"type": "number", "exclusiveMinimum": 5},
              "explanation": {"type": "string", "enum": ["robots_blocked", "paginated", "js_rendered", "sitemap_stale", "noindexed_in_cms", "other"]},
              "note": {"type": "string", "minLength": 10}
            }
          }
        }
      }
    },
    "incoming_counts": {
      "type": "object",
      "required": ["basis", "pages", "over_linked_hubs"],
      "additionalProperties": false,
      "properties": {
        "basis": {"const": "contextual"},
        "pages": {
          "type": "array",
          "minItems": 1,
          "items": {
            "type": "object",
            "required": ["url", "contextual_incoming", "boilerplate_incoming"],
            "additionalProperties": false,
            "properties": {
              "url": {"$ref": "#/definitions/url"},
              "contextual_incoming": {"$ref": "#/definitions/count"},
              "boilerplate_incoming": {"$ref": "#/definitions/count"}
            }
          }
        },
        "over_linked_hubs": {
          "type": "array",
          "items": {
            "type": "object",
            "required": ["url", "contextual_incoming", "threshold"],
            "additionalProperties": false,
            "properties": {
              "url": {"$ref": "#/definitions/url"},
              "contextual_incoming": {"$ref": "#/definitions/count"},
              "threshold": {"type": "integer", "minimum": 1}
            }
          }
        }
      }
    },
    "orphans": {
      "type": "array",
      "items": {
        "type": "object",
        "required": ["url", "found_via", "contextual_incoming", "decision"],
        "additionalProperties": false,
        "properties": {
          "url": {"$ref": "#/definitions/url"},
          "found_via": {"type": "array", "minItems": 1, "uniqueItems": true, "items": {"type": "string", "enum": ["sitemap", "analytics", "crawl"]}},
          "contextual_incoming": {"const": 0},
          "decision": {"type": "string", "enum": ["rewire", "redirect", "deindex"]},
          "source_url": {"$ref": "#/definitions/url"},
          "anchor_text": {"type": "string", "minLength": 3},
          "redirect_target": {"$ref": "#/definitions/url"}
        },
        "allOf": [
          {"if": {"properties": {"decision": {"const": "rewire"}}}, "then": {"required": ["source_url", "anchor_text"]}},
          {"if": {"properties": {"decision": {"const": "redirect"}}}, "then": {"required": ["redirect_target"]}}
        ]
      }
    },
    "clusters": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "object",
        "required": ["pillar_url", "cluster_pages", "cluster_to_pillar_links", "structurally_incomplete"],
        "additionalProperties": false,
        "properties": {
          "pillar_url": {"$ref": "#/definitions/url"},
          "cluster_pages": {
            "type": "array",
            "minItems": 5,
            "items": {
              "type": "object",
              "required": ["url", "links_to_pillar", "pillar_links_to_it"],
              "additionalProperties": false,
              "properties": {
                "url": {"$ref": "#/definitions/url"},
                "links_to_pillar": {"type": "boolean"},
                "pillar_links_to_it": {"type": "boolean"}
              }
            }
          },
          "cluster_to_pillar_links": {"$ref": "#/definitions/count"},
          "structurally_incomplete": {"type": "boolean"}
        },
        "if": {"properties": {"cluster_to_pillar_links": {"maximum": 4}}},
        "then": {"properties": {"structurally_incomplete": {"const": true}}},
        "else": {"properties": {"structurally_incomplete": {"const": false}}}
      }
    },
    "anchor_text": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "object",
        "required": ["url", "total_links", "anchors"],
        "additionalProperties": false,
        "properties": {
          "url": {"$ref": "#/definitions/url"},
          "total_links": {"type": "integer", "minimum": 0},
          "anchors": {
            "type": "array",
            "items": {
              "type": "object",
              "required": ["anchor", "count", "share", "generic"],
              "additionalProperties": false,
              "properties": {
                "anchor": {"type": "string"},
                "count": {"type": "integer", "minimum": 1},
                "share": {"type": "number", "minimum": 0, "maximum": 1},
                "generic": {"type": "boolean"}
              },
              "if": {"properties": {"anchor": {"anyOf": [{"$ref": "#/definitions/generic_anchor"}, {"pattern": "^https?://"}]}}},
              "then": {"properties": {"generic": {"const": true}}}
            }
          }
        }
      }
    },
    "hygiene_findings": {
      "type": "array",
      "items": {
        "type": "object",
        "required": ["source_url", "current_target", "final_url", "issue"],
        "additionalProperties": false,
        "properties": {
          "source_url": {"$ref": "#/definitions/url"},
          "current_target": {"$ref": "#/definitions/url"},
          "final_url": {"$ref": "#/definitions/url"},
          "issue": {"type": "string", "enum": ["redirect_3xx", "client_error_4xx", "server_error_5xx", "noindex_target", "canonical_elsewhere", "nofollow"]}
        }
      }
    },
    "rewire_plan": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "object",
        "required": ["source_url", "target_url", "anchor_text", "placement", "action", "owner", "due_date"],
        "additionalProperties": false,
        "properties": {
          "source_url": {"$ref": "#/definitions/url"},
          "target_url": {"$ref": "#/definitions/url"},
          "anchor_text": {"type": "string", "minLength": 3, "not": {"anyOf": [{"$ref": "#/definitions/generic_anchor"}, {"pattern": "^https?://"}]}},
          "placement": {"type": "string", "minLength": 20},
          "action": {"type": "string", "enum": ["add", "change_anchor", "remove", "redirect"]},
          "owner": {"type": "string", "minLength": 2, "not": {"enum": ["team", "we", "us", "content team", "seo team"]}},
          "due_date": {"$ref": "#/definitions/date"}
        }
      }
    },
    "gsc_baseline": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "object",
        "required": ["url", "clicks", "impressions", "average_position", "contextual_incoming", "window_days"],
        "additionalProperties": false,
        "properties": {
          "url": {"$ref": "#/definitions/url"},
          "clicks": {"$ref": "#/definitions/count"},
          "impressions": {"$ref": "#/definitions/count"},
          "average_position": {"type": "number", "minimum": 1},
          "contextual_incoming": {"$ref": "#/definitions/count"},
          "window_days": {"const": 28}
        }
      }
    },
    "remeasurement": {
      "type": "object",
      "required": ["date", "metrics"],
      "additionalProperties": false,
      "properties": {
        "date": {"$ref": "#/definitions/date"},
        "metrics": {
          "type": "array",
          "minItems": 3,
          "uniqueItems": true,
          "items": {"type": "string", "enum": ["clicks", "impressions", "average_position"]}
        }
      }
    }
  }
}

