{
  "site": "example.com",
  "audit_period": {"start": "2026-08-01", "end": "2026-08-31"},
  "crawl": {
    "crawler": "Screaming Frog SEO Spider 21",
    "crawl_date": "2026-08-20",
    "javascript_rendered": true,
    "indexable_pages": 412,
    "sitemap_urls": 430,
    "cms_published_pages": 445,
    "discrepancies": [
      {"source": "cms", "gap_pct": 7.4, "explanation": "paginated", "note": "33 paginated archive pages are published in the CMS but carry noindex, so they are not indexable"}
    ]
  },
  "incoming_counts": {
    "basis": "contextual",
    "pages": [
      {"url": "https://example.com/guides/email-deliverability", "contextual_incoming": 21, "boilerplate_incoming": 412},
      {"url": "https://example.com/guides/spf-records", "contextual_incoming": 6, "boilerplate_incoming": 412},
      {"url": "https://example.com/guides/dmarc-setup", "contextual_incoming": 4, "boilerplate_incoming": 412},
      {"url": "https://example.com/blog/warmup-schedule-2024", "contextual_incoming": 0, "boilerplate_incoming": 412},
      {"url": "https://example.com/blog/2023-deliverability-report", "contextual_incoming": 0, "boilerplate_incoming": 412},
      {"url": "https://example.com/blog", "contextual_incoming": 380, "boilerplate_incoming": 412}
    ],
    "over_linked_hubs": [
      {"url": "https://example.com/blog", "contextual_incoming": 380, "threshold": 100}
    ]
  },
  "orphans": [
    {"url": "https://example.com/blog/warmup-schedule-2024", "found_via": ["sitemap", "analytics"], "contextual_incoming": 0, "decision": "rewire", "source_url": "https://example.com/guides/email-deliverability", "anchor_text": "a week-by-week domain warm-up schedule"},
    {"url": "https://example.com/blog/2023-deliverability-report", "found_via": ["sitemap"], "contextual_incoming": 0, "decision": "redirect", "redirect_target": "https://example.com/blog/2026-deliverability-report"}
  ],
  "clusters": [
    {
      "pillar_url": "https://example.com/guides/email-deliverability",
      "cluster_pages": [
        {"url": "https://example.com/guides/spf-records", "links_to_pillar": true, "pillar_links_to_it": true},
        {"url": "https://example.com/guides/dkim-signing", "links_to_pillar": true, "pillar_links_to_it": true},
        {"url": "https://example.com/guides/dmarc-setup", "links_to_pillar": true, "pillar_links_to_it": false},
        {"url": "https://example.com/guides/bounce-handling", "links_to_pillar": true, "pillar_links_to_it": true},
        {"url": "https://example.com/guides/list-hygiene", "links_to_pillar": true, "pillar_links_to_it": true},
        {"url": "https://example.com/guides/feedback-loops", "links_to_pillar": false, "pillar_links_to_it": true}
      ],
      "cluster_to_pillar_links": 5,
      "structurally_incomplete": false
    }
  ],
  "anchor_text": [
    {"url": "https://example.com/guides/email-deliverability", "total_links": 21, "anchors": [
      {"anchor": "email deliverability guide", "count": 12, "share": 0.571, "generic": false},
      {"anchor": "read more", "count": 6, "share": 0.286, "generic": true},
      {"anchor": "how inbox placement works", "count": 3, "share": 0.143, "generic": false}
    ]},
    {"url": "https://example.com/guides/dmarc-setup", "total_links": 4, "anchors": [
      {"anchor": "setting up DMARC", "count": 4, "share": 1, "generic": false}
    ]},
    {"url": "https://example.com/blog/warmup-schedule-2024", "total_links": 0, "anchors": []}
  ],
  "hygiene_findings": [
    {"source_url": "https://example.com/guides/spf-records", "current_target": "https://example.com/blog/old-dmarc-post", "final_url": "https://example.com/guides/dmarc-setup", "issue": "redirect_3xx"},
    {"source_url": "https://example.com/guides/list-hygiene", "current_target": "https://example.com/tools/bounce-checker", "final_url": "https://example.com/tools/bounce-checker", "issue": "nofollow"}
  ],
  "rewire_plan": [
    {"source_url": "https://example.com/guides/email-deliverability", "target_url": "https://example.com/guides/dmarc-setup", "anchor_text": "configure a DMARC policy", "placement": "paragraph 4 of the Authentication section, sentence on policy enforcement", "action": "add", "owner": "Olena K.", "due_date": "2026-09-30"},
    {"source_url": "https://example.com/guides/feedback-loops", "target_url": "https://example.com/guides/email-deliverability", "anchor_text": "the wider deliverability picture", "placement": "introduction, second sentence, where the pillar topic is first mentioned", "action": "add", "owner": "Olena K.", "due_date": "2026-09-30"},
    {"source_url": "https://example.com/guides/email-deliverability", "target_url": "https://example.com/blog/warmup-schedule-2024", "anchor_text": "a week-by-week domain warm-up schedule", "placement": "Warm-up section, end of the first paragraph on sending volume ramps", "action": "add", "owner": "Olena K.", "due_date": "2026-09-30"},
    {"source_url": "https://example.com/guides/spf-records", "target_url": "https://example.com/guides/dmarc-setup", "anchor_text": "setting up DMARC after SPF", "placement": "Next steps section, replace the link to the old DMARC post", "action": "change_anchor", "owner": "Olena K.", "due_date": "2026-09-30"}
  ],
  "gsc_baseline": [
    {"url": "https://example.com/guides/dmarc-setup", "clicks": 410, "impressions": 18200, "average_position": 8.4, "contextual_incoming": 4, "window_days": 28},
    {"url": "https://example.com/guides/email-deliverability", "clicks": 1930, "impressions": 61000, "average_position": 5.1, "contextual_incoming": 21, "window_days": 28},
    {"url": "https://example.com/blog/warmup-schedule-2024", "clicks": 12, "impressions": 900, "average_position": 31.2, "contextual_incoming": 0, "window_days": 28}
  ],
  "remeasurement": {"date": "2026-11-30", "metrics": ["clicks", "impressions", "average_position"]}
}

